// Deterministic framebuffer evidence for the actual native renderer. No menus, network, timer or recording.
#include "renderer.hpp"
#include "weapon_commands.hpp"
#include <cstdlib>
#include <optional>
int main(int argc,char **argv){
    try {
        std::string map,content,output,waterOutput,action,outfit="outfit-cream",loadout,zoneFile,waterQuality="refracted",glowColor,actorAction,colorBlind="off";unsigned zoneStatus=0,zoneTrack=0;bool zoneGold=false;bool simulateFire=false,aura=true,firstPersonGlow=true;bool flashlight=false,triggers=false,msaa=false,sourceLook=false,requireWater=false;int frames=2;bool actor=false;float opacity=.45,actorYaw=0,actorPitch=0,actorSpeed=0;uint32_t actorFlags=2;float eye[3]={};bool explicitEye=false,worldOnly=false;double yaw=0,pitch=0,seconds=2;int weapon=-1;
        for(int i=1;i<argc;i++){
            const std::string arg=argv[i];auto value=[&](){if(++i>=argc)throw std::runtime_error("missing argument value");return std::string(argv[i]);};
            auto number=[&](){const auto text=value();size_t used=0;const double n=std::stod(text,&used);if(used!=text.size()||!std::isfinite(n))throw std::runtime_error("invalid finite number");return n;};
            if(arg=="--map")map=value();else if(arg=="--content-root")content=value();else if(arg=="--out")output=value();else if(arg=="--eye"){for(float &n:eye)n=number();explicitEye=true;}else if(arg=="--yaw")yaw=number();else if(arg=="--pitch")pitch=number();else if(arg=="--seconds")seconds=number();else if(arg=="--water-quality")waterQuality=value();else if(arg=="--frames")frames=int(number());else if(arg=="--zone-file")zoneFile=value();else if(arg=="--color-blind")colorBlind=value();else if(arg=="--zone-status")zoneStatus=unsigned(number());else if(arg=="--zone-track")zoneTrack=unsigned(number());else if(arg=="--zone-gold")zoneGold=true;else if(arg=="--require-water")requireWater=true;else if(arg=="--msaa")msaa=true;else if(arg=="--source-look")sourceLook=true;else if(arg=="--flashlight")flashlight=true;else if(arg=="--triggers")triggers=true;else if(arg=="--weapon")weapon=int(number());else if(arg=="--world-only")worldOnly=true;else if(arg=="--water-json")waterOutput=value();else if(arg=="--action")action=value();else if(arg=="--outfit")outfit=value();else if(arg=="--loadout")loadout=value();else if(arg=="--glow")glowColor=value();else if(arg=="--no-aura")aura=false;else if(arg=="--firstperson-glow-off")firstPersonGlow=false;else if(arg=="--simulate-fire")simulateFire=true;else if(arg=="--actor-action")actorAction=value();else if(arg=="--actor")actor=true;else if(arg=="--opacity")opacity=number();else if(arg=="--actor-yaw")actorYaw=number();else if(arg=="--actor-pitch")actorPitch=number();else if(arg=="--actor-flags")actorFlags=uint32_t(number());else if(arg=="--actor-speed")actorSpeed=number();else throw std::runtime_error("unknown render smoke option: "+arg);
        }
        if(map.empty()||output.empty())throw std::runtime_error("usage: --map FILE --out FILE.ppm [--content-root DIR] [--eye x y z] [--yaw DEG] [--pitch DEG] [--weapon ID] [--world-only] [--seconds TIME]");
        if(frames<1||frames>10000||seconds<0)throw std::runtime_error("frames must be 1..10000 and seconds nonnegative");if(waterQuality!="simple"&&waterQuality!="refracted")throw std::runtime_error("water-quality must be simple or refracted");
        if(!SDL_Init(SDL_INIT_VIDEO))throw std::runtime_error(SDL_GetError());struct Sdl{~Sdl(){SDL_Quit();}}sdl;
        SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,3);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,3);SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_CORE);SDL_GL_SetAttribute(SDL_GL_DEPTH_SIZE,24);
        auto *window=SDL_CreateWindow("Native render evidence",1280,720,SDL_WINDOW_OPENGL|SDL_WINDOW_HIDDEN);if(!window)throw std::runtime_error(SDL_GetError());struct Window{SDL_Window*w;~Window(){SDL_DestroyWindow(w);}}cleanup{window};
        const auto context=SDL_GL_CreateContext(window);if(!context)throw std::runtime_error(SDL_GetError());struct Context{SDL_GLContext c;~Context(){SDL_GL_DestroyContext(c);}}contextCleanup{context};SDL_GL_MakeCurrent(window,context);SDL_GL_SetSwapInterval(0);
        Gl gl;gl.load();using Core=std::unique_ptr<BhContext,decltype(&bh_destroy)>;Core core(bh_create(),&bh_destroy);if(!core||!bh_load_map(core.get(),map.c_str(),content.empty()?nullptr:content.c_str()))throw std::runtime_error(core?bh_last_error(core.get()):"native core creation failed");
        if(!waterOutput.empty()){size_t n=0;const char *json=bh_water_json(core.get(),&n);std::ofstream f(waterOutput,std::ios::binary);if(json&&n)f.write(json,n);if(!f)throw std::runtime_error("cannot write water evidence");}
        BhSettings settings{};bh_default_settings(&settings);if(!bh_set_settings(core.get(),&settings))throw std::runtime_error(bh_last_error(core.get()));BhSnapshot snapshot{};bh_snapshot(core.get(),&snapshot);
        if(!explicitEye)for(int k=0;k<3;k++)eye[k]=snapshot.player.position[k]+(k==2?snapshot.player.view_offset_z:0);
        native::Input input;input.set_angles(pitch,yaw);Renderer renderer(gl,core.get());renderer.set_viewmodel_visible(!worldOnly&&weapon<0);renderer.set_cosmetics(outfit,loadout);renderer.set_water_quality(waterQuality=="refracted"?1:0);renderer.set_flashlight(flashlight);renderer.set_triggers_visible(triggers);renderer.set_color_blind(colorBlind);
        renderer.graphics_settings({{"graphicsAntialias", msaa}});
        renderer.set_source_look(sourceLook);

        if(!zoneFile.empty()){std::ifstream f(zoneFile);if(!f)throw std::runtime_error("zone file unavailable");nlohmann::json json;f>>json;if(json.is_object())json=json.value("zones",nlohmann::json::array());std::vector<BhZone> zones;for(const auto &z:json){BhZone zone{};const auto kind=z.value("kind","");if(kind=="start")zone.kind=0;else if(kind=="end")zone.kind=1;else if(kind=="stage")zone.kind=2;else if(kind=="checkpoint")zone.kind=3;else continue;zone.track=z.value("track",0u);zone.index=z.value("index",0u);for(int k=0;k<3;k++){zone.mins[k]=z.at("mins").at(k);zone.maxs[k]=z.at("maxs").at(k);}zones.push_back(zone);}renderer.set_zones(zones);}

        BhRunState zoneState{};zoneState.status=zoneStatus;zoneState.track=zoneTrack;renderer.set_zone_state(zoneTrack,zoneState,zoneGold);
        if(!waterOutput.empty()){size_t n=0;const char *raw=bh_water_json(core.get(),&n);auto json=raw&&n?nlohmann::json::parse(raw,raw+n):nlohmann::json::object();json["renderVolumes"]=renderer.water_diagnostics();std::ofstream f(waterOutput);f<<json.dump(2);if(!f)throw std::runtime_error("cannot write water diagnostics");}
        std::optional<native_render::Glow> glow;if(!glowColor.empty())glow=native_render::parse_glow({{"enabled",true},{"aura",aura},{"color",glowColor},{"intensity",1}});renderer.set_player_glow(glow);renderer.set_glow_visible(true,firstPersonGlow);
        std::optional<native_render::Actor> visibleActor;
        if(actor){native_render::Actor a;a.playerGlow=glow;a.id="smoke";a.name="Native bunny";a.outfit=outfit;a.loadout=loadout;a.opacity=opacity;for(int k=0;k<3;k++)a.frame.position[k]=snapshot.player.position[k];a.frame.yaw=actorYaw;a.frame.pitch=actorPitch;a.frame.velocity[0]=actorSpeed;a.frame.flags=actorFlags;a.frame.weapon=weapon>0?weapon:1;visibleActor=a;renderer.set_room_actors({a});}
        int width=0,height=0;SDL_GetWindowSizeInPixels(window,&width,&height);
        std::unique_ptr<NativeViewmodel> preview;if(!worldOnly&&weapon>=0&&!simulateFire)preview=std::make_unique<NativeViewmodel>(gl);if(preview){preview->cosmetics(outfit,loadout);preview->player_glow(glow);preview->glow_visibility(true,firstPersonGlow);}
        if(simulateFire){const unsigned wanted=weapon>0?unsigned(weapon):2;BhCmd cmd{};cmd.yaw=float(yaw);cmd.pitch=float(pitch);cmd.buttons=wanted<<native::give_shift;BhState state{};if(!bh_step(core.get(),&cmd,&state))throw std::runtime_error(bh_last_error(core.get()));bool fired=false;for(unsigned tick=0;tick<512;tick++){cmd.buttons=native::attack;if(!bh_step(core.get(),&cmd,&state))throw std::runtime_error(bh_last_error(core.get()));BhAttackReport attack{};if(bh_attack_report(core.get(),&attack)){renderer.simulation_tick();std::cout<<"Authoritative core fire: weapon="<<attack.weapon<<", mode="<<attack.mode<<", hit="<<attack.hit<<"\n";fired=true;break;}}if(!fired)throw std::runtime_error("Core weapon did not fire");bh_snapshot(core.get(),&snapshot);renderer.set_viewmodel_visible(!worldOnly);if(!explicitEye)for(int k=0;k<3;k++)eye[k]=snapshot.player.position[k]+(k==2?snapshot.player.view_offset_z:0);}
        if(action=="inspect"){if(preview)preview->inspect_press();else renderer.inspect_press();}
        for(int i=0;i<frames;i++){const double time=frames==1?seconds:seconds*i/(frames-1);if(visibleActor){visibleActor->inspect=i==0&&actorAction=="inspect"?1:0;visibleActor->attack=i==0&&actorAction=="fire"?1:0;renderer.set_room_actors({*visibleActor});}renderer.draw(width,height,eye,input,&snapshot,time);if(preview)preview->draw(width,height,snapshot,weapon,i==0&&action=="reload"?4:0,i==0&&(action=="fire"||action=="stab"),action=="stab"?2:1,time);}
        if (requireWater && !renderer.refraction_captures())
            throw std::runtime_error("No visible refracted water was captured");
        std::cout << "Refraction captures: " << renderer.refraction_captures() << '\n';
        const auto error=gl.GetError();if(error!=GL_NO_ERROR)throw std::runtime_error("native render GL error "+std::to_string(error));renderer.screenshot(output,width,height);
        std::cout<<"Native render evidence: "<<width<<'x'<<height<<", yaw="<<yaw<<", pitch="<<pitch<<", camera="<<eye[0]<<','<<eye[1]<<','<<eye[2]<<"; GL_NO_ERROR\n";
        return 0;
    } catch(const std::exception &error){std::cerr<<"Render smoke: "<<error.what()<<'\n';return 1;}
}
